using YunXiaoJob.Application.DTOs.Responses;
using YunXiaoJob.Application.Interfaces.Repositories;
using YunXiaoJob.Domain.Enums;
namespace YunXiaoJob.Application.UseCases.Dashboards;
public class GetPlatformDashboardUseCase { private readonly IUserRepository _users; private readonly IDashboardRepository _dashboard; public GetPlatformDashboardUseCase(IUserRepository users, IDashboardRepository dashboard) { _users = users; _dashboard = dashboard; } public async Task<PlatformDashboardResponse> ExecuteAsync(Guid currentUserId, CancellationToken ct = default) { var user = await _users.GetByIdAsync(currentUserId, ct) ?? throw new UnauthorizedAccessException(); if (user.PlatformRole != PlatformRole.Admin) throw new UnauthorizedAccessException(); var x = await _dashboard.GetPlatformCountsAsync(ct); return new PlatformDashboardResponse(x.Users, x.Candidates, x.Companies, x.ActiveCompanies, x.JobPostings, x.PublishedJobPostings, x.Applications); } }
public class GetCompanyDashboardUseCase { private readonly ICompanyRepository _companies; private readonly IDashboardRepository _dashboard; public GetCompanyDashboardUseCase(ICompanyRepository companies, IDashboardRepository dashboard) { _companies = companies; _dashboard = dashboard; } public async Task<CompanyDashboardResponse> ExecuteAsync(Guid companyId, Guid currentUserId, CancellationToken ct = default) { var member = await _companies.GetMemberAsync(companyId, currentUserId, ct); if (member is null || !member.IsActive || member.Role is CompanyMemberRole.Recruiter) throw new UnauthorizedAccessException(); var x = await _dashboard.GetCompanyCountsAsync(companyId, ct); return new CompanyDashboardResponse(x.JobPostings, x.PublishedJobPostings, x.Applications, x.ApplicationsByStatus); } }
